// Infinitary queue 12. Generated by Infinitary from one source; a newer Infinitary offers its update as a pull request, so change it there, not by hand.
/**
 * The shipped queue's rules (docs/forge.md, "The shipped queue"), written
 * once and naming no host. Infinitary copies this file into a project with
 * one host part beside it (github.mjs on GitHub), which reads the host's
 * pull requests, statuses and runs into the shapes below and writes back
 * what these rules decide. Nothing here reads a person's words: every rule
 * reads typed states, the host's run readings and git's compose output.
 *
 * A change's whole state is one status, infinitary/queue, on its current
 * version. Infinitary writes it waiting when its approver's merge click
 * approves that version; the queue writes the rest:
 *
 *   pending "Waiting for the batch check"     approved, waiting for a batch
 *   pending "In batch run N"                  the change is in batch run N
 *   pending "Paused after batch run N; ..."   batch run N failed; the queue waits for a fix
 *   success "Passed batch run N; tree T"      the change may merge
 *   failure "<reason>"                        the change goes back to its author
 *
 * A red batch first confirms: the project's batch checks run once more on
 * the same composed batch, told the failed jobs and the failed test files,
 * and decide themselves what runs again. A green confirm passes the batch.
 * A red one, or a failure no log named a test file for, fixes forward: it
 * pauses every change in it and blames none, and no batch forms until a
 * fix declared for that pause is approved, or a by-hand resume or
 * send-back turns the paused changes back to waiting. A checks result
 * outside success/failure with no passing confirmation starts a fresh
 * batch once; if a member's preceding batch also lacked a verdict, it
 * pauses instead. The status history records that outcome before its
 * ordinary waiting/paused status.
 */

export const QUEUE = "infinitary/queue";
/** A local approval hold removes merge eligibility without revoking the saved head itself. */
export const REMOVED = "Not queued: merge approval held or withdrawn";
export const WAITING = "Waiting for the batch check";
/**
 * The label a repair crewmate puts on its change to declare it the pause's
 * fix. It declares a fix only for a pause that began before it was put on.
 */
export const FIX_LABEL = "infinitary-queue-fix";
/**
 * The label someone who may merge puts on a change to queue its version
 * without Infinitary. The queue reads it as one act, at the version it went
 * on, and takes it off once read: a later push leaves the queue until the
 * label goes on again.
 */
export const QUEUE_LABEL = "infinitary-queue";
/** The label on the one open issue that holds a pause. */
export const PAUSE_LABEL = "infinitary-queue-paused";
/** The queue's job that runs the project's batch checks; a host names that job's own jobs under it. */
export const CHECKS_JOB = "Batch checks";
/** The queue's job that runs them again to confirm a red batch. */
export const CONFIRM_JOB = "Batch confirm";
/** The longest status description hosts keep. */
const DESCRIPTION_MAX = 140;

const IN_BATCH = /^In batch run (\d+)$/;
const PAUSED = /^Paused after batch run (\d+)(?:;|$)/;
const PASSED = /^Passed batch run (\d+); tree ([0-9a-f]{40,64})$/;
const NO_VERDICT = /^No verdict from batch run (\d+)$/;
const PAUSE_MARKER = /<!-- infinitary-queue (\{.*?\}) -->/;

/**
 * Whether a queue label puts a change's version in the queue: only from
 * someone the host says may merge it (`trusted`), on a change that targets
 * `main`, at the version the label went on (`moved` when it was pushed
 * since), and only while that version is not already in the queue. A
 * failed version may be queued again by a new label.
 */
export function labelQueues({ entry, main, trusted, moved }) {
  const said = (words) => `#${entry.number}: ${words}`;
  if (!trusted)
    return {
      queue: false,
      reason: said("the label is from someone who may not merge it, so it queues nothing."),
    };
  if (entry.base !== main)
    return {
      queue: false,
      reason: said(`it targets ${entry.base}, not ${main}, so the label queues nothing.`),
    };
  if (moved)
    return {
      queue: false,
      reason: said(
        "it was pushed after the label went on; put the label on again to queue that version.",
      ),
    };
  if (entry.queue && entry.queue.kind !== "failed")
    return { queue: false, reason: said("this version is already in the queue.") };
  return { queue: true, reason: said("the label queued this version.") };
}

export const inBatch = (run) => `In batch run ${run}`;
export const passed = (run, tree) => `Passed batch run ${run}; tree ${tree}`;
/** A pending observation kept before the ordinary waiting or paused status. */
export const noVerdict = (run) => `No verdict from batch run ${run}`;

/**
 * A change's queue state from the queue statuses on its version, newest
 * first. `since` is when the newest unbroken stretch of pending statuses
 * began: the approval mark, which orders the batch. A paused change also
 * says when its pause began (`pausedAt`): the first paused status of that
 * run in the newest unbroken stretch of them.
 */
export function readQueueState(statuses) {
  const [latest] = statuses;
  if (!latest) return null;
  let since = latest.createdAt;
  if (latest.state === "pending")
    for (const status of statuses) {
      if (status.state !== "pending") break;
      since = status.createdAt;
    }
  const base = {
    state: latest.state,
    description: latest.description ?? "",
    url: latest.url ?? "",
    since,
  };
  const kind = queueKind(base.state, base.description);
  const previousNoVerdict = priorMissingVerdict(
    statuses,
    kind.kind === "in-batch" ? kind.run : undefined,
  );
  let pausedAt;
  if (kind.kind === "paused")
    for (const status of statuses) {
      const each = queueKind(status.state, status.description);
      if (each.kind !== "paused" || each.run !== kind.run) break;
      pausedAt = status.createdAt;
    }
  return {
    ...base,
    ...kind,
    ...(previousNoVerdict === undefined ? {} : { previousNoVerdict }),
    ...(pausedAt === undefined ? {} : { pausedAt }),
  };
}

/**
 * Read the nearest earlier batch's recorded outcome, not a count of old
 * outages. Skip this run's active marks; a completed attempt of the same
 * run still counts. A known result in between ends the missing-verdict chain.
 */
function priorMissingVerdict(statuses, currentRun) {
  let missing;
  let outcome = false;
  for (const status of statuses) {
    const absent = status.state === "pending" && NO_VERDICT.exec(status.description ?? "");
    if (absent) {
      missing = Number(absent[1]);
      outcome = true;
    }
    const kind = queueKind(status.state, status.description);
    if (kind.kind === "paused" || status.state !== "pending") outcome = true;
    if (kind.kind !== "in-batch") continue;
    if (kind.run === currentRun && !outcome) continue;
    return missing === kind.run ? kind.run : undefined;
  }
  return undefined;
}

/**
 * What one queue status says, from its state and description alone: the
 * one grammar every teammate's Infinitary and the shipped queue share.
 */
export function queueKind(state, description) {
  const words = description ?? "";
  const batch = IN_BATCH.exec(words);
  const pause = PAUSED.exec(words);
  const green = PASSED.exec(words);
  if (state === "pending" && batch) return { kind: "in-batch", run: Number(batch[1]) };
  if (state === "pending" && pause) return { kind: "paused", run: Number(pause[1]) };
  if (state === "pending") return { kind: "waiting" };
  if (state === "success" && green)
    return { kind: "passed", run: Number(green[1]), tree: green[2] };
  return { kind: "failed" };
}

/**
 * A batch run owns its changes while it runs. A run that ended without
 * writing its verdict owns nothing, so its changes join the next batch.
 */
export function ownsChanges(run) {
  return Boolean(run) && run.status !== "completed";
}

const byApproval = (a, b) => a.queue.since.localeCompare(b.queue.since) || a.number - b.number;

/**
 * What the queue does now, from every open change's queue state and the
 * readings of the runs those states name. A batch forms only after the last
 * green batch has fully merged and while no run owns a change. While a
 * batch is paused, nothing forms until a waiting change was labelled the
 * fix after the pause began (`fixLabelledAt`, when the label was last put
 * on): then every paused change waits again (`resumes`) and the batch takes
 * them, every waiting change and the fix (`fixes`). A label put on before
 * the pause began, such as one left from an earlier pause, declares no fix
 * for it, so that change waits like any other and the pause holds. Only
 * changes that target `main` take part: a stacked change waits until it
 * targets it. The host part composes the batch onto `main` as it stands
 * after this read, never an earlier version: a green change still open here
 * holds the batch, and one that merged before the read is in its base.
 */
export function formBatch(entries, runs, main) {
  const queued = entries.filter((entry) => entry.queue && entry.base === main);
  const merging = queued.filter((entry) => entry.queue.kind === "passed");
  if (merging.length)
    return {
      action: "wait",
      reason: `A green batch is still merging: ${merging.map((entry) => `#${entry.number}`).join(", ")}.`,
      members: [],
      resumes: [],
      fixes: [],
    };
  const owned = queued.filter(
    (entry) => entry.queue.kind === "in-batch" && ownsChanges(runs.get(entry.queue.run)),
  );
  if (owned.length)
    return {
      action: "wait",
      reason: `Batch run ${owned[0].queue.run} is running.`,
      members: [],
      resumes: [],
      fixes: [],
    };
  const paused = queued.filter((entry) => entry.queue.kind === "paused");
  const waiting = queued.filter(
    (entry) => entry.queue.kind === "waiting" || entry.queue.kind === "in-batch",
  );
  const labelled = waiting.filter((entry) => entry.fix);
  // A fix comes after every pause it ends, so after the latest of their
  // starts; a start or a label time no status or event gave ends nothing.
  const began = Math.max(...paused.map((entry) => Date.parse(entry.queue.pausedAt ?? "")));
  const fixes = labelled.filter((entry) => Date.parse(entry.fixLabelledAt ?? "") > began);
  if (paused.length && !fixes.length) {
    const earlier = labelled.length
      ? ` ${numbered(labelled)} ${labelled.length > 1 ? "carry" : "carries"} a fix label not put on after this pause began, so the pause holds.`
      : "";
    return {
      action: "wait",
      reason: `Batch run ${paused[0].queue.run} failed, so the queue is paused until its fix is approved, or a resume or a send-back by hand.${earlier}`,
      members: [],
      resumes: [],
      fixes: [],
    };
  }
  const members = [...paused, ...waiting]
    .sort(byApproval)
    .map((entry) => ({ number: entry.number, head: entry.head }));
  const resumes = paused.map((entry) => ({ number: entry.number, head: entry.head }));
  if (!members.length)
    return {
      action: "none",
      reason: "No approved change is waiting.",
      members,
      resumes,
      fixes: [],
    };
  return {
    action: "sweep",
    reason: paused.length
      ? `${numbered(fixes)} ${fixes.length > 1 ? "are the approved fixes" : "is the approved fix"}, so the pause ends and ${members.length} changes go in one batch.`
      : `${members.length} approved changes are waiting.`,
    members,
    resumes,
    fixes: paused.length ? fixes.map((entry) => entry.number) : [],
  };
}

const numbered = (entries) => entries.map((entry) => `#${entry.number}`).join(", ");

/**
 * The writes that end a pause by hand: every paused change but `except`
 * (the one a send-back names) waits again, keeping its place in approval
 * order, and the caller starts the next batch. An already-failed run ended
 * by a send-back (`endedRun`) releases its remaining members the same way.
 */
export function resume(entries, { url, except, endedRun }) {
  return entries
    .filter(
      (entry) =>
        entry.number !== except &&
        (entry.queue?.kind === "paused" ||
          (endedRun !== undefined &&
            entry.queue?.kind === "in-batch" &&
            entry.queue.run === endedRun)),
    )
    .map((entry) => ({
      number: entry.number,
      head: entry.head,
      state: "pending",
      description: WAITING,
      url,
    }));
}

/**
 * A send-back's write: the change fails with the reason, at most the length
 * hosts keep, on the version the queue holds it at - its current version,
 * while that version's queue state is paused, or in a batch run whose
 * verdict then takes the send-back as its answer. A change whose pull
 * request moved on since, such as a fix pushed after the pause, carries
 * neither there, so there is nothing to send back (null): the host part
 * writes nothing, and that version's own checks and approval decide it.
 */
export function sendBack(entry, { reason, url }) {
  if (!reason?.trim()) throw new Error("A send-back needs a reason.");
  const kind = entry.queue?.kind;
  if (kind !== "paused" && kind !== "in-batch") return null;
  return {
    number: entry.number,
    head: entry.head,
    state: "failure",
    description: `Sent back: ${reason.trim()}`.slice(0, DESCRIPTION_MAX),
    url,
  };
}

/**
 * What a by-hand answer says on the pause's issue and in its run: a resume,
 * a send-back (`number`) that wrote its failure (`sent`), or one that wrote
 * nothing, saying what the change's current version reads instead (`queue`,
 * its queue state there). `change` is what the host calls a pull request.
 */
export function answerWords({
  number,
  sent,
  queue,
  reason,
  resumed,
  endedRun,
  change = "pull request",
}) {
  const why = reason.trim();
  const rest =
    endedRun === undefined
      ? `${resumed} paused changes wait again.`
      : `${resumed} changes wait again after ending batch run ${endedRun}.`;
  if (number === undefined)
    return {
      issue: `The queue was resumed by hand: ${why}`,
      log: `The queue was resumed; ${rest}`,
    };
  if (sent)
    return {
      issue: `#${number} was sent back by hand: ${why}`,
      log: `#${number} was sent back; ${rest}`,
    };
  const read = queue
    ? `its current version is not paused but reads "${queue.description}"`
    : `its ${change} moved on to a version no batch has run`;
  return {
    issue: `#${number} was not sent back: ${read}, so the queue wrote nothing on it and resumed the rest. The reason given: ${why}`,
    log: `#${number} was not sent back, since ${read}; ${rest}`,
  };
}

/** The `<number>:<version>` list the compose step takes, in batch order. */
export const headList = (members) =>
  members.map((member) => `${member.number}:${member.head}`).join(" ");

/**
 * The compose step's output: the default branch's version the batch
 * composes onto, read after the queue (`base`), the tree, and which changes
 * merged, which conflict with main alone, and which conflict only with an
 * earlier change of this batch (they wait for the next one).
 */
export function readComposition(output, members) {
  const lines = output.trim().split("\n");
  const said = (word) =>
    lines.filter((line) => line.startsWith(`${word} `)).map((line) => Number(line.split(" ")[1]));
  const pick = (numbers) => members.filter((member) => numbers.includes(member.number));
  const named = (word) => lines.find((line) => line.startsWith(`${word} `))?.split(" ")[1] ?? "";
  const base = named("base");
  const tree = named("tree");
  if (!/^[0-9a-f]{40,64}$/.test(base)) throw new Error("The batch composition reported no base.");
  if (!/^[0-9a-f]{40,64}$/.test(tree)) throw new Error("The batch composition reported no tree.");
  return {
    base,
    tree,
    merged: pick(said("merged")),
    conflictsMain: pick(said("conflict-main")),
    conflictsBatch: pick(said("conflict-batch")),
  };
}

/** The write for a change that conflicts with main alone: it goes back to be brought up to date. */
export function conflictsWithMain(member, url) {
  return {
    ...member,
    state: "failure",
    description: "Conflicts with the default branch: bring the branch up to date",
    url,
  };
}

/**
 * What a red batch's confirm runs, from each failed job of the batch checks
 * with the test files its log named: the failed jobs' names, one a line,
 * and the failed files, separated by spaces. A failed job that is not one
 * of the batch checks' own, or whose log named no test file, failed for
 * something no rerun of a test answers, so there is no confirm (null) and
 * the batch pauses.
 */
export function confirmPlan(failedJobs) {
  const lead = `${CHECKS_JOB} / `;
  if (!failedJobs.length) return null;
  if (failedJobs.some((job) => !job.name.startsWith(lead) || !job.files.length)) return null;
  return {
    jobs: [...new Set(failedJobs.map((job) => job.name.slice(lead.length)))].join("\n"),
    files: [...new Set(failedJobs.flatMap((job) => job.files))].join(" "),
  };
}

/**
 * The verdict a batch run writes once its checks end. Only changes still in
 * this run at the same version are written: one sent back by hand, or
 * pushed again, keeps what it has. Green passes them, and so does a red
 * batch whose confirm passed (`confirm`, the confirm's result: what failed
 * passed again on the same batch). Red with a change
 * sent back by hand during the run takes that send-back as its answer, and
 * the rest wait for a new batch without it. An incomplete result gets one
 * fresh batch unless a preceding batch also lacked a verdict. Other red
 * results pause every change: `pause` names them for the host part, which opens the pause's
 * issue and writes each one's paused status with its link.
 */
export function verdict({
  run,
  runUrl,
  result,
  tree,
  members,
  current,
  failed = [],
  failedFiles = [],
  confirm = "",
  jobs = [],
}) {
  const queueOf = (member) => {
    const now = current.get(member.number);
    return now?.head === member.head ? now.queue : null;
  };
  const still = members.filter((member) => {
    const queue = queueOf(member);
    return queue?.kind === "in-batch" && queue.run === run;
  });
  if (!still.length) {
    const paused = members.some((member) => {
      const queue = queueOf(member);
      return queue?.kind === "paused" && queue.run === run;
    });
    return {
      writes: [],
      next: paused ? null : "form",
      pause: null,
      summary: paused
        ? "This batch is already paused; nothing starts again."
        : "No change is still in this batch.",
    };
  }
  if (result === "success" || (result === "failure" && confirm === "success"))
    return {
      writes: still.map((member) => ({
        ...member,
        state: "success",
        description: passed(run, tree),
        url: runUrl,
      })),
      next: null,
      pause: null,
      summary:
        result === "success"
          ? "The batch passed."
          : `The batch passed on its confirm: ${failedNames(failed, failedFiles)} failed in its checks and passed when they ran again on the same batch, so a flaky test still needs an owner.`,
    };
  const sentBack = members.filter((member) => {
    const now = current.get(member.number);
    return (now?.head === member.head ? now.queue : now?.swept)?.kind === "failed";
  });
  if (sentBack.length) {
    const named = sentBack.map((member) => `#${member.number}`).join(", ");
    return {
      writes: still.map((member) => ({
        ...member,
        state: "pending",
        description: WAITING,
        url: runUrl,
      })),
      next: "form",
      pause: null,
      summary: `The batch failed and ${named} went back by hand, so the rest wait for a new batch without ${sentBack.length > 1 ? "them" : "it"}.`,
    };
  }
  // A host result outside success/failure is incomplete verification, not a
  // failing test. The captain-approved recovery tries a fresh batch once;
  // any member whose preceding batch also lacked a verdict stops the chain.
  // Record that typed fact before waiting/pausing, in the same status history
  // read above. No job count or absence of failures can manufacture success.
  const incomplete = result !== "failure" && confirm !== "success";
  const observations = incomplete
    ? still.map((member) => ({
        ...member,
        state: "pending",
        description: noVerdict(run),
        url: runUrl,
      }))
    : [];
  const previousNoVerdict = [
    ...new Set(
      still.flatMap((member) => {
        const previous = queueOf(member)?.previousNoVerdict;
        return previous === undefined ? [] : [previous];
      }),
    ),
  ];
  if (incomplete && !previousNoVerdict.length)
    return {
      writes: [
        ...observations,
        ...still.map((member) => ({
          ...member,
          state: "pending",
          description: WAITING,
          url: runUrl,
        })),
      ],
      next: "form",
      pause: null,
      summary:
        "The batch returned no verdict. Its changes wait for a fresh batch; only that batch's own successful checks can pass them.",
    };
  const description = pauseDescription(run, failed, failedFiles);
  const confirmed = confirm === "failure";
  return {
    writes: observations,
    next: null,
    pause: {
      run,
      description,
      members: still,
      failed,
      failedFiles,
      confirmed,
      result,
      confirm,
      jobs,
      previousNoVerdict: incomplete ? previousNoVerdict : [],
    },
    summary: incomplete
      ? "The preceding batch also returned no verdict, so the queue is paused instead of starting another batch. No incomplete result passes a change."
      : failed.length
        ? "The batch failed, so the queue is paused: these changes and every new approval wait until a fix is approved, or a resume or a send-back by hand."
        : "The batch verdict did not pass, so the queue is paused. No failed job was reported; successful or skipped jobs cannot replace the missing verdict.",
  };
}

/** Each paused change's write once the pause's issue exists, linking to it. */
export function pauseWrites(pause, issueUrl) {
  return pause.members.map((member) => ({
    ...member,
    state: "pending",
    description: pause.description,
    url: issueUrl,
  }));
}

const failedNames = (failed, failedFiles) =>
  failedFiles.length
    ? failedFiles.map((entry) => entry.file).join(", ")
    : failed.map((check) => check.name).join(", ") || "a check";

const touchedBy = ({ touchedBy: numbers }) =>
  numbers.length
    ? `touched by ${numbers.map((number) => `#${number}`).join(", ")}`
    : "no change here touches it";

/** A paused status's description, at most the length hosts keep. */
function pauseDescription(run, failed, failedFiles) {
  const [first] = failedFiles;
  const more = failedFiles.length > 1 ? ` (+${failedFiles.length - 1} more)` : "";
  const what = first
    ? `${first.file}${more} failed; ${touchedBy(first)}`
    : failed.length
      ? `${failed[0].name} failed`
      : "batch verdict did not pass; no failed job reported";
  return `Paused after batch run ${run}; ${what}`.slice(0, DESCRIPTION_MAX);
}

/**
 * The pause's one issue: its title, and a body naming the failed checks,
 * the failed test files and the paused changes, with one marker line every
 * teammate's Infinitary reads for the run and the paused changes.
 */
export function pauseIssue(pause, runUrl) {
  const failed = pause.failed.length
    ? pause.failed.map((check) => `- [${check.name}](${check.url || runUrl})`).join("\n")
    : "No failed job was reported. Successful or skipped jobs do not prove that the batch verdict passed.";
  const files = pause.failedFiles.length
    ? `\n\nFailed test files:\n${pause.failedFiles.map((entry) => `- \`${entry.file}\` (${touchedBy(entry)})`).join("\n")}`
    : "";
  const changes = pause.members.map((member) => `- #${member.number}`).join("\n");
  const marker = JSON.stringify({
    run: pause.run,
    changes: pause.members.map((member) => member.number),
  });
  return {
    title: pause.failed.length
      ? `The batch is paused: batch run ${pause.run} failed`
      : `The batch is paused: batch run ${pause.run} has no passing verdict`,
    body: [
      !pause.failed.length
        ? `Batch run ${pause.run} has no passing verdict, so the queue paused. No change is blamed, and no test retry is selected without a failed test.`
        : pause.confirmed
          ? `Batch run ${pause.run} failed, and its failed checks failed again when they ran once more on the same batch, so the queue paused. No change is blamed.`
          : `Batch run ${pause.run} failed, so the queue paused. No change is blamed, and nothing ran again: a failed job's log named no failed test file to run again.`,
      `Failed checks:\n${failed}${files}`,
      ...(pause.previousNoVerdict?.length
        ? [
            `No automatic restart: a preceding batch also returned no verdict (${pause.previousNoVerdict.join(", ")}).`,
          ]
        : []),
      ...(pause.result !== undefined
        ? [
            `Workflow results: batch checks \`${pause.result || "not reported"}\`; confirmation \`${pause.confirm || "not reported"}\`.`,
          ]
        : []),
      ...(!pause.failed.length
        ? [
            `Recorded jobs in [batch run ${pause.run}](${runUrl}):\n${
              pause.jobs?.length
                ? pause.jobs
                    .map(
                      (job) =>
                        `- [${job.name}](${job.url || runUrl}): ${job.status ?? "status not reported"} / ${job.conclusion ?? "no conclusion"}`,
                    )
                    .join("\n")
                : "No job results were available."
            }`,
            "Inspect the workflow result and its job records before resuming. The underlying cause is not established by an empty failure list.",
          ]
        : []),
      `Paused changes, which go in the next batch:\n${changes}`,
      "Whoever takes this issue repairs it. A change labelled `" +
        FIX_LABEL +
        "` after this pause began ends it once the change is approved. A label put on before then, such as one left from an earlier pause, does not: to make that change this pause's fix, take the label off and put it on again. A resume or a send-back by hand ends it too.",
      `<!-- infinitary-queue ${marker} -->`,
    ].join("\n\n"),
  };
}

/** The run and paused changes a pause's issue names, or null when the body carries no marker. */
export function readPauseMarker(body) {
  const found = PAUSE_MARKER.exec(body ?? "");
  if (!found) return null;
  try {
    const parsed = JSON.parse(found[1]);
    if (!Number.isSafeInteger(parsed.run) || !Array.isArray(parsed.changes)) return null;
    return {
      run: parsed.run,
      changes: parsed.changes.filter((number) => Number.isSafeInteger(number)),
    };
  } catch {
    return null;
  }
}

// A test file's path as common runners print it, from the project's root.
const TEST_FILE = /(?:^|\s)((?:[\w.@-]+\/)*[\w.@-]+\.(?:test|spec)\.[cm]?[jt]sx?)(?=[\s:[]|$)/;
// Vitest's line naming the test file an unhandled error came from: such an
// error fails the run even when every test passed, and prints no FAIL line.
const UNHANDLED_IN = /^\s*This error originated in "((?:[\w.@-]+\/)*[\w.@-]+)" test file\./;
// A CI log's timestamp before each line, and a terminal's colors.
const LOG_PREFIX = /^\d{4}-\d\d-\d\dT[\d:.]+Z /;
// biome-ignore lint/suspicious/noControlCharactersInRegex: a terminal's color codes start with ESC
const COLORS = /\u001b\[[0-9;]*m/g;

/**
 * The test files a failed job's log names as failed, in the order it names
 * them: Vitest and Jest's FAIL lines, the tests listed under Playwright's
 * closing "N failed" line, and the test file Vitest says an unhandled error
 * originated in.
 */
export function failedTestFiles(log) {
  const files = [];
  let inFailedList = false;
  for (const raw of log.split("\n")) {
    const line = raw.replace(LOG_PREFIX, "").replace(COLORS, "").trimEnd();
    if (/^\s*\d+ failed$/.test(line)) {
      inFailedList = true;
      continue;
    }
    const listed = inFailedList && /^\s{4}\S/.test(line);
    inFailedList = listed;
    const file =
      listed || /^\s*FAIL\s/.test(line) ? TEST_FILE.exec(line)?.[1] : UNHANDLED_IN.exec(line)?.[1];
    if (file && !files.includes(file)) files.push(file);
  }
  return files;
}
